package com.gameaggregator.contractservice.api;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.util.UUID;public final class ContractDtos{private ContractDtos(){}public record Create(@NotBlank String contractNumber,@NotNull UUID createdBy){}public record Party(@NotNull UUID partyId,@Pattern(regexp="STUDIO|PUBLISHER|CLIENT|PLATFORM")String partyType,@NotBlank String role){}public record Version(@NotNull LocalDate effectiveDate,LocalDate expirationDate,@NotBlank String territoriesJson,@NotBlank String gameRightsJson,@NotBlank String revenueAgreementJson,String attachmentKey){}public record Approval(@NotNull UUID actorId){}public record Termination(@NotNull UUID actorId,@NotBlank String reason){}}